var BID=[[178.41,1200],[178.40,2400],[178.39,1850],[178.38,3100],[178.37,2050],[178.36,4300],[178.35,5600],[178.34,3200],[178.33,6100],[178.32,7400]];
var ASK=[[178.43,1050],[178.44,2900],[178.45,1600],[178.46,3400],[178.47,2200],[178.48,5100],[178.49,4000],[178.50,8200],[178.51,3300],[178.52,6600]];
var MID=(BID[0][0]+ASK[0][0])/2, MAXQ=30000, side='B';
root.querySelector('.cdp-sweep-curve-sp').textContent=((ASK[0][0]-BID[0][0])/MID*1e4).toFixed(2)+'bp';
function sweep(q,book){
  var left=q,cost=0,lvl=0,worst=book[0][0],f=0,i;
  for(i=0;i<book.length&&left>0.0001;i++){
    var t=Math.min(left,book[i][1]);cost+=t*book[i][0];left-=t;f+=t;worst=book[i][0];lvl++;
  }
  var vwap=f?cost/f:MID;
  return {vwap:vwap,slip:(vwap-MID)/MID*1e4,lvl:lvl,worst:worst,not:cost,f:f};
}
var N=64,buy=[],sell=[],amax=0,i;
for(i=0;i<=N;i++){
  var q=MAXQ*i/N;
  var b=q?sweep(q,ASK).slip:0, s=q?sweep(q,BID).slip:0;
  buy.push(b);sell.push(s);
  amax=Math.max(amax,Math.abs(b),Math.abs(s));
}
var ym=amax*1.18||1;
function X(i){return (i/N*288).toFixed(2);}
function Y(v){return (52-v/ym*46).toFixed(2);}
function line(a){var d='M0,'+Y(a[0]);for(var k=1;k<=N;k++)d+=' L'+X(k)+','+Y(a[k]);return d;}
function fill(a){return line(a)+' L288,52 L0,52 Z';}
root.querySelector('.cdp-sweep-curve-bl').setAttribute('d',line(buy));
root.querySelector('.cdp-sweep-curve-sl').setAttribute('d',line(sell));
root.querySelector('.cdp-sweep-curve-bf').setAttribute('d',fill(buy));
root.querySelector('.cdp-sweep-curve-sf').setAttribute('d',fill(sell));
var rng=root.querySelector('.cdp-sweep-curve-rng'),cur=root.querySelector('.cdp-sweep-curve-cur'),dot=root.querySelector('.cdp-sweep-curve-dot');
var v1=root.querySelector('.cdp-sweep-curve-v1'),v2=root.querySelector('.cdp-sweep-curve-v2'),v3=root.querySelector('.cdp-sweep-curve-v3');
var v4=root.querySelector('.cdp-sweep-curve-v4'),v5=root.querySelector('.cdp-sweep-curve-v5'),v6=root.querySelector('.cdp-sweep-curve-v6');
function money(n){return n>=1e6?'$'+(n/1e6).toFixed(2)+'M':'$'+Math.round(n/1e3)+'k';}
function paint(){
  var q=+rng.value, book=side==='B'?ASK:BID, r=sweep(q,book);
  var x=q/MAXQ*288;
  cur.setAttribute('x1',x.toFixed(2));cur.setAttribute('x2',x.toFixed(2));
  dot.setAttribute('cx',x.toFixed(2));dot.setAttribute('cy',Y(r.slip));
  v1.textContent=(side==='B'?'+':'-')+r.f.toLocaleString('en-US');
  v2.textContent=r.vwap.toFixed(4);
  v3.textContent=(r.slip>=0?'+':'')+r.slip.toFixed(2)+'bp';
  v3.className='cdp-sweep-curve-'+(r.slip>=0?'up':'dn');
  v4.textContent=r.lvl+' / '+book.length;
  v5.textContent=r.worst.toFixed(2);
  v6.textContent=money(r.not);
}
rng.addEventListener('input',paint);
root.querySelectorAll('.cdp-sweep-curve-side').forEach(function(b){
  b.addEventListener('click',function(){
    side=b.getAttribute('data-s');
    root.querySelectorAll('.cdp-sweep-curve-side').forEach(function(o){
      var on=o===b;o.classList.toggle('cdp-sweep-curve-on',on);o.setAttribute('aria-pressed',on?'true':'false');
    });
    paint();
  });
});
paint();

