var ASK=[[6412.50,112],[6412.75,88],[6413.00,141],[6413.25,96],[6413.50,203],[6413.75,74],[6414.00,168],[6414.25,245]];
var BID=[[6412.25,134],[6412.00,97],[6411.75,186],[6411.50,71],[6411.25,212],[6411.00,158],[6410.75,93],[6410.50,227]];
var body=root.querySelector('.cdp-book-ladder-body'),msg=root.querySelector('.cdp-book-ladder-msg');
var mid=(ASK[0][0]+BID[0][0])/2, spr=ASK[0][0]-BID[0][0];
var mx=0,rows=[],i;
for(i=0;i<ASK.length;i++)mx=Math.max(mx,ASK[i][1]);
for(i=0;i<BID.length;i++)mx=Math.max(mx,BID[i][1]);
function mk(px,sz,cum,cls){
  var r=document.createElement('div');
  r.className='cdp-book-ladder-row '+cls;
  r.setAttribute('role','row');
  r.innerHTML='<span class="cdp-book-ladder-px"></span><span class="cdp-book-ladder-sz"></span><span class="cdp-book-ladder-bar"><i></i></span><span class="cdp-book-ladder-cum"></span>';
  r.children[0].textContent=px.toFixed(2);
  r.children[1].textContent=sz;
  r.children[3].textContent=cum;
  r.dataset.px=px.toFixed(2);
  r.dataset.side=cls.indexOf('ask')>-1?'BUY':'SELL';
  r.dataset.cum=cum;
  body.appendChild(r);
  requestAnimationFrame(function(){if(!root.isConnected)return;r.querySelector('i').style.setProperty('--cdp-bl-w',(sz/mx*100).toFixed(1)+'%');});
  return r;
}
for(i=ASK.length-1;i>=0;i--){
  var cum=0;for(var k=0;k<=i;k++)cum+=ASK[k][1];
  rows.push(mk(ASK[i][0],ASK[i][1],cum,'cdp-book-ladder-ask'));
}
var sp=document.createElement('div');
sp.className='cdp-book-ladder-spr';
sp.innerHTML='<span>MID '+mid.toFixed(3)+' &middot; SPRD '+spr.toFixed(2)+' &middot; 1 TK &middot; '+(spr/mid*1e4).toFixed(2)+' BP</span>';
body.appendChild(sp);
var bidRows=[];
for(i=0;i<BID.length;i++){
  var cb=0;for(var j=0;j<=i;j++)cb+=BID[j][1];
  bidRows.push(mk(BID[i][0],BID[i][1],cb,'cdp-book-ladder-bid'));
}
rows=rows.concat(bidRows);
var sel=ASK.length-1;
function mark(){
  for(var i=0;i<rows.length;i++)rows[i].classList.toggle('cdp-book-ladder-sel',i===sel);
}
function send(){
  var r=rows[sel];
  msg.innerHTML='<span class="cdp-book-ladder-live">SENT</span> '+r.dataset.side+' 5 ESZ5 @ '+r.dataset.px+' IOC &middot; cum '+r.dataset.cum;
  r.classList.remove('cdp-book-ladder-fire');void r.offsetWidth;r.classList.add('cdp-book-ladder-fire');
}
body.addEventListener('click',function(e){
  var r=e.target.closest('.cdp-book-ladder-row');if(!r)return;
  sel=rows.indexOf(r);mark();send();
});
root.addEventListener('keydown',function(e){
  if(e.key==='ArrowDown'){sel=Math.min(rows.length-1,sel+1);mark();e.preventDefault();}
  else if(e.key==='ArrowUp'){sel=Math.max(0,sel-1);mark();e.preventDefault();}
  else if(e.key==='Enter'){send();e.preventDefault();}
});
mark();

