var NL=25,TICK=0.5,bidPx=68412.5,askPx=68413.0;
var bq=[],aq=[],i;
for(i=0;i<NL;i++){bq.push(0.6+Math.random()*3.4);aq.push(0.6+Math.random()*3.4);}
var bandsEl=root.querySelector('.cdp-imbalance-gauge-bands'),histEl=root.querySelector('.cdp-imbalance-gauge-hist');
var BANDS=[5,10,25],rowEls=[];
BANDS.forEach(function(n){
  var r=document.createElement('div');
  r.className='cdp-imbalance-gauge-row';
  r.innerHTML='<span class="cdp-imbalance-gauge-dep">TOP '+n+'</span><span class="cdp-imbalance-gauge-b"></span><span class="cdp-imbalance-gauge-mini"><i></i></span><span class="cdp-imbalance-gauge-a"></span>';
  bandsEl.appendChild(r);rowEls.push(r);
});
var HN=40,hist=[],cells=[],hv=(Math.random()-0.5)*0.24;
for(i=0;i<HN;i++){
  var c=document.createElement('span');c.className='cdp-imbalance-gauge-c';c.innerHTML='<i></i>';
  histEl.appendChild(c);cells.push(c.firstChild);
  hv=Math.max(-0.55,Math.min(0.55,hv+(Math.random()-0.5)*0.17));
  hist.push(hv);
}
var val=root.querySelector('.cdp-imbalance-gauge-val'),lab=root.querySelector('.cdp-imbalance-gauge-lab');
var fill=root.querySelector('.cdp-imbalance-gauge-fill'),nee=root.querySelector('.cdp-imbalance-gauge-nee');
var quote=root.querySelector('.cdp-imbalance-gauge-quote'),mp=root.querySelector('.cdp-imbalance-gauge-mp'),tob=root.querySelector('.cdp-imbalance-gauge-tob');
function sum(a,n){var s=0;for(var k=0;k<n;k++)s+=a[k];return s;}
function fmt(x){return x.toFixed(2);}
function render(){
  var mid=(bidPx+askPx)/2;
  quote.textContent=bidPx.toFixed(1)+' x '+askPx.toFixed(1)+'  '+((askPx-bidPx)/mid*1e4).toFixed(2)+'bp';
  BANDS.forEach(function(n,k){
    var b=sum(bq,n),a=sum(aq,n),im=(b-a)/(b+a);
    var r=rowEls[k];
    r.children[1].textContent=fmt(b);
    r.children[3].textContent=fmt(a);
    var bar=r.children[2].firstChild;
    bar.style.left=(im>=0?50:50+im*50)+'%';
    bar.style.width=Math.abs(im)*50+'%';
    bar.style.background=im>=0?'#25E07A':'#FF5C6C';
    if(n===10){
      var pc=im*100;
      val.textContent=(pc>=0?'+':'')+pc.toFixed(1)+'%';
      root.classList.remove('cdp-imbalance-gauge-bid','cdp-imbalance-gauge-ask');
      if(Math.abs(pc)>=8){
        root.classList.add(pc>0?'cdp-imbalance-gauge-bid':'cdp-imbalance-gauge-ask');
        lab.textContent=(pc>0?'BID':'ASK')+' SKEW';
      } else lab.textContent='BALANCED';
      fill.style.left=(im>=0?50:50+im*50)+'%';
      fill.style.width=Math.abs(im)*50+'%';
      fill.style.background=im>=0?'rgba(37,224,122,.55)':'rgba(255,92,108,.55)';
      nee.style.left=(50+im*50)+'%';
      hist.shift();hist.push(im);
      for(var q=0;q<HN;q++){
        var v=hist[q],h=Math.min(48,Math.abs(v)*90);
        var e=cells[q];
        e.style.height=Math.max(1,h)+'%';
        e.style.background=v>=0?'rgba(37,224,122,'+(0.35+Math.abs(v)).toFixed(2)+')':'rgba(255,92,108,'+(0.35+Math.abs(v)).toFixed(2)+')';
        if(v>=0){e.style.bottom='50%';e.style.top='auto';}else{e.style.top='50%';e.style.bottom='auto';}
      }
    }
  });
  var micro=(bidPx*aq[0]+askPx*bq[0])/(aq[0]+bq[0]);
  var off=(micro-mid)/TICK;
  mp.textContent=micro.toFixed(2)+' ('+(off>=0?'+':'')+off.toFixed(2)+' tk)';
