.cdp-iceberg-scan-conf i{position:absolute;left:0;top:0;bottom:0;width:0;background:linear-gradient(90deg,rgba(255,194,77,.35),rgba(255,194,77,.75));transition:width .4s ease}
.cdp-iceberg-scan-conf b{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:7.5px;font-weight:700;color:#E4EBF7;letter-spacing:.05em}
.cdp-iceberg-scan-spr{display:flex;align-items:center;gap:5px;margin:3px 0;font-size:7px;letter-spacing:.1em;color:#6E7C97}
.cdp-iceberg-scan-spr:before,.cdp-iceberg-scan-spr:after{content:"";flex:1;height:1px;background:rgba(110,168,255,.25)}
@keyframes cdp-iceberg-scan-hit{0%{background:rgba(255,194,77,.3)}100%{background:transparent}}
.cdp-iceberg-scan-fire{animation:cdp-iceberg-scan-hit .6s ease-out}
.cdp-iceberg-scan-log{height:41px;overflow:hidden;margin-top:6px;padding-top:5px;border-top:1px solid #1C2432;font-size:7.5px;line-height:1.5;color:#5B6883}
.cdp-iceberg-scan-log div{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cdp-iceberg-scan-log b{color:#FFC24D;font-weight:600}
.cdp-iceberg-scan-ft{margin-top:5px;padding-top:5px;border-top:1px solid #1C2432;font-size:8px;letter-spacing:.05em;color:#5B6883}
.cdp-iceberg-scan-ft b{color:#D6DFEF;font-weight:600}
@media (prefers-reduced-motion:reduce){.cdp-iceberg-scan-live i{animation:none}.cdp-iceberg-scan-fire{animation:none}.cdp-iceberg-scan-conf i{transition:none}}

js:
var L=[
 {px:232.50,side:'A',disp:2000,n:9},
 {px:232.48,side:'A',disp:500,n:2},
 {px:232.46,side:'A',disp:1200,n:5},
 {px:232.44,side:'B',disp:1500,n:6},
 {px:232.42,side:'B',disp:800,n:3},
 {px:232.40,side:'B',disp:2500,n:11}
];
var body=root.querySelector('.cdp-iceberg-scan-body'),log=root.querySelector('.cdp-iceberg-scan-log'),ft=root.querySelector('.cdp-iceberg-scan-ft');
var bestBid=232.44,bestAsk=232.46,mid=(bestBid+bestAsk)/2;
function conf(n){return Math.min(97,30+n*6);}
L.forEach(function(l,i){
  if(l.side==='B'&&(i===0||L[i-1].side==='A')){
    var sp=document.createElement('div');
    sp.className='cdp-iceberg-scan-spr';
    sp.innerHTML='<span>TOUCH '+bestBid.toFixed(2)+' / '+bestAsk.toFixed(2)+' &middot; '+((bestAsk-bestBid)/mid*1e4).toFixed(2)+'BP</span>';
    body.appendChild(sp);
  }
  var r=document.createElement('div');
  r.className='cdp-iceberg-scan-row cdp-iceberg-scan-'+(l.side==='A'?'ask':'bid');
  r.innerHTML='<span class="cdp-iceberg-scan-sd">'+l.side+'</span>'+
    '<span class="cdp-iceberg-scan-px">'+l.px.toFixed(2)+'</span>'+
    '<span class="cdp-iceberg-scan-dp">'+l.disp.toLocaleString('en-US')+'</span>'+
    '<span class="cdp-iceberg-scan-n"></span>'+
    '<span class="cdp-iceberg-scan-hd2"></span>'+
    '<span class="cdp-iceberg-scan-conf"><i></i><b></b></span>';
  body.appendChild(r);
  l.el=r;
});
function row(l){
  l.el.querySelector('.cdp-iceberg-scan-n').textContent=l.n;
  l.el.querySelector('.cdp-iceberg-scan-hd2').textContent=(l.n*l.disp).toLocaleString('en-US');
  var c=conf(l.n);
  l.el.querySelector('.cdp-iceberg-scan-conf i').style.width=c+'%';
  l.el.querySelector('.cdp-iceberg-scan-conf b').textContent=c;
}
function foot(){
  var h=0;
  for(var i=0;i<L.length;i++)h+=L[i].n*L[i].disp;
  ft.innerHTML='EST HIDDEN <b>'+h.toLocaleString('en-US')+'</b> sh &middot; <b>EUR '+(h*mid/1e6).toFixed(2)+'M</b> &middot; '+L.length+' LVLS FLAGGED';
}
L.forEach(row);foot();
var t=51727.412;
function stamp(){
  var s=t%60,m=(t/60|0)%60,h=(t/3600|0);
  return ('0'+h).slice(-2)+':'+('0'+m).slice(-2)+':'+('0'+s.toFixed(3)).slice(-6);
}
function line(l){
  var d=document.createElement('div');
  d.innerHTML=stamp()+' <b>REFILL</b> '+(l.side==='B'?'BID':'ASK')+' '+l.px.toFixed(2)+' x'+l.disp.toLocaleString('en-US')+' n='+l.n;
  log.insertBefore(d,log.firstChild);
  while(log.children.length>3)log.removeChild(log.lastChild);
}
line(L[5]);line(L[0]);line(L[3]);
if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
setInterval(function(){
  if(!root.isConnected)return;
  var l=L[Math.floor(Math.random()*L.length)];
  t+=0.3+Math.random()*1.4;
  l.n++;row(l);foot();line(l);
  l.el.classList.remove('cdp-iceberg-scan-fire');
  void l.el.offsetWidth;
  l.el.classList.add('cdp-iceberg-scan-fire');
},950);
